package billing

import (
	"fmt"
	"strconv"
	"strings"
)

// ParseCents converts a decimal amount such as "12.34" or "7" into cents.
func ParseCents(text string) (int64, error) {
	whole, fraction, _ := strings.Cut(text, ".")
	if whole == "" || len(fraction) > 2 {
		return 0, fmt.Errorf("billing: parse cents %q: want digits with at most two decimals", text)
	}
	cents, err := strconv.ParseInt(whole+padFraction(fraction), 10, 64)
	if err != nil {
		return 0, fmt.Errorf("billing: parse cents %q: %w", text, err)
	}
	return cents, nil
}

func padFraction(fraction string) string {
	return (fraction + "00")[:2]
}
